// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address requester, bytes32 digest, uint256 utxoSize, bytes memory redeemerOutputScript, uint256 requestedFee, bytes memory outpoint) public {
        vm.assume(caller != address(0));
        vm.assume(redeemerOutputScript.length <= 100);
        vm.assume(outpoint.length <= 100);
        vm.prank(caller);
        (bool success, bytes memory returnData) = address(c).call(abi.encodeWithSignature("logRedemptionRequested(address,bytes32,uint256,bytes,uint256,bytes)", requester, digest, utxoSize, redeemerOutputScript, requestedFee, outpoint));
        require(success, "call reverted");
        bool returned = abi.decode(returnData, (bool));
        assertTrue(returned == c.approvedToLog(caller), "logRedemptionRequested return should equal approvedToLog(caller)");
    }
}

